<?php
require __DIR__.'/../config/app.php';
$me=require_role('admin');
ensure_committee_schema();
$userType=($_GET['role']??'student')==='committee'?'committee':'student';
$error='';$search=trim((string)($_GET['q']??''));
$eventIds=static function(array $submitted,array $events): array {
    $allowed=array_fill_keys(array_map(static fn($event)=>(int)$event['id'],$events),true);
    $ids=[];
    foreach($submitted as $value){$id=(int)$value;if(isset($allowed[$id]))$ids[$id]=$id;}
    return array_values($ids);
};
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$action=(string)($_POST['action']??'');
    if($action==='create_student'){
        $name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$nameLength=preg_match_all('/./us',$name);
        if($name===''||$nameLength===false||$nameLength>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/@marwadiuniversity\.ac\.in$/i',$email)||strlen($password)<8){flash('Enter a name, a valid @marwadiuniversity.ac.in email, and a password of at least 8 characters.','error');go('admin/users.php?role=student');}
        try{$pdo=db();$pdo->beginTransaction();$insert=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,is_active) VALUES(?,?,?,'student',1)");$insert->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$studentId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO student_profiles(user_id) VALUES(?)')->execute([$studentId]);$pdo->prepare('INSERT INTO user_settings(user_id) VALUES(?)')->execute([$studentId]);$pdo->commit();flash('Student account created.');}
        catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('Could not create this account. Check that the email is not already registered.','error');}go('admin/users.php?role=student');
    }
    if($action==='set_student_status'){
        $studentId=(int)($_POST['student_id']??0);$active=(int)($_POST['is_active']??0)===1?1:0;
        try{$q=db()->prepare("UPDATE users SET is_active=? WHERE id=? AND role='student'");$q->execute([$active,$studentId]);flash($q->rowCount()?'Student account status updated.':'Student account was not changed.');}
        catch(Throwable $t){flash('Could not update the student account status.','error');}
        go('admin/users.php?role=student');
    }
    if($action==='create_committee'||$action==='assign_events'){
        $name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$nameLength=preg_match_all('/./us',$name);
        try{
            $pdo=db();$events=$pdo->query('SELECT id FROM events ORDER BY title')->fetchAll();$ids=$eventIds((array)($_POST['event_ids']??[]),$events);
            if($action==='create_committee'&&($name===''||$nameLength===false||$nameLength>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/@marwadiuniversity\.ac\.in$/i',$email)||strlen($password)<8||!$ids))throw new RuntimeException('Enter a name, university email, password of at least 8 characters, and assign at least one event.');
            $pdo->beginTransaction();
            if($action==='create_committee'){$insert=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,is_active) VALUES(?,?,?,'committee',1)");$insert->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$committeeId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO user_settings(user_id) VALUES(?)')->execute([$committeeId]);}
            else{$committeeId=(int)($_POST['committee_id']??0);$check=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='committee'");$check->execute([$committeeId]);if(!$check->fetchColumn())throw new RuntimeException('Committee account not found.');$pdo->prepare('DELETE FROM committee_event_assignments WHERE committee_user_id=?')->execute([$committeeId]);}
            $assign=$pdo->prepare('INSERT INTO committee_event_assignments(committee_user_id,event_id,assigned_by) VALUES(?,?,?)');foreach($ids as $eventId)$assign->execute([$committeeId,$eventId,$me['id']]);$pdo->commit();flash($action==='create_committee'?'Committee account created and events assigned.':'Assigned events updated.');
        }catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash($t instanceof RuntimeException?$t->getMessage():'Could not save the committee account. Check that the email is not already registered.','error');}
        go('admin/users.php?role=committee');
    }
    if($action==='set_committee_status'){
        $committeeId=(int)($_POST['committee_id']??0);$active=(int)($_POST['is_active']??0)===1?1:0;
        try{$q=db()->prepare("UPDATE users SET is_active=? WHERE id=? AND role='committee'");$q->execute([$active,$committeeId]);flash($q->rowCount()?'Committee account status updated.':'Committee account was not changed.');}
        catch(Throwable $t){flash('Could not update committee account status.','error');}
        go('admin/users.php?role=committee');
    }
    http_response_code(405);exit('Unsupported user action.');
}
$rows=[];$events=[];$totalStudents=0;$totalAdmins=0;$totalCommittee=0;
try{$pdo=db();$totalStudents=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$totalAdmins=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();$totalCommittee=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='committee'")->fetchColumn();
    if($userType==='student'){$q=$pdo->prepare("SELECT id,name,email,role,created_at,is_active FROM users WHERE role='student' AND (?='' OR name LIKE ? OR email LIKE ?) ORDER BY name");$term='%'.$search.'%';$q->execute([$search,$term,$term]);$rows=$q->fetchAll();}
    else{$events=$pdo->query('SELECT id,title,event_date,venue FROM events ORDER BY event_date,title')->fetchAll();$q=$pdo->prepare("SELECT u.id,u.name,u.email,u.created_at,u.is_active,GROUP_CONCAT(DISTINCT e.title ORDER BY e.title SEPARATOR '||') assigned_events,GROUP_CONCAT(DISTINCT e.id ORDER BY e.title) assigned_event_ids FROM users u LEFT JOIN committee_event_assignments cea ON cea.committee_user_id=u.id LEFT JOIN events e ON e.id=cea.event_id WHERE u.role='committee' AND (?='' OR u.name LIKE ? OR u.email LIKE ?) GROUP BY u.id ORDER BY u.name");$term='%'.$search.'%';$q->execute([$search,$term,$term]);$rows=$q->fetchAll();}
}catch(Throwable $t){$error='Could not load account records. Check the database connection.';}
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="eventhub-'.$userType.'-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Name','Email','Role','Status','Joined']);foreach($rows as $r)fputcsv($out,[$r['name'],$r['email'],$userType,$r['is_active']?'Active':'Inactive',$r['created_at']]);fclose($out);exit;}
$perPage=25;$totalRecords=count($rows);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$rows=array_slice($rows,($currentPage-1)*$perPage,$perPage);$pageTitle=$userType==='student'?'Students':'Committee Members';$bodyClass='dashboard-page admin-page';$activePage='users';$adminSection='users';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">ACCOUNT DIRECTORY</span><h1><?=$userType==='student'?'Students':'Committee Members'?></h1><p><?=$userType==='student'?'Manage student accounts without changing any user roles.':'Create committee accounts and give access only to the events assigned to each member.'?></p></div></header><?php require __DIR__.'/section-nav.php';?><section class="admin-work-card"><form method="get" class="admin-report-filters"><input type="hidden" name="role" value="<?=e($userType)?>"><input name="q" value="<?=e($search)?>" placeholder="Search name or email"><button class="btn primary">Search</button><a class="btn outline" href="<?=url('admin/users.php?'.http_build_query(['role'=>$userType,'q'=>$search,'export'=>'csv']))?>">Export CSV</a></form></section><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><div class="admin-summary-grid"><article class="admin-summary-card"><span class="admin-summary-icon teal"><?=eventhub_icon('people')?></span><div><small>Student accounts</small><strong><?=$totalStudents?></strong></div></article><article class="admin-summary-card"><span class="admin-summary-icon violet"><?=eventhub_icon('user')?></span><div><small>Admin accounts</small><strong><?=$totalAdmins?></strong></div></article><article class="admin-summary-card"><span class="admin-summary-icon mint"><?=eventhub_icon('people')?></span><div><small>Committee accounts</small><strong><?=$totalCommittee?></strong></div></article></div><?php if($userType==='student'):?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('user')?></span><div><h2>Create student account</h2><p>Students must use a Marwadi University email address.</p></div></div><form method="post" class="form-card admin-event-form" autocomplete="off"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_student"><div class="admin-form-grid"><label>Student name<input name="name" maxlength="120" required></label><label>University email<input type="email" name="email" pattern=".+@marwadiuniversity\.ac\.in" required placeholder="name@marwadiuniversity.ac.in"></label><label>Temporary password<input type="password" name="password" minlength="8" required></label></div><div class="admin-form-actions"><span class="profile-role">Account role is set to Student.</span><button class="btn primary" type="submit">Create Student</button></div></form></section><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('people')?></span><div><h2>Student directory <span class="admin-count"><?=count($rows)?></span></h2><p>University student accounts and status.</p></div></div><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Joined</th><th>State</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><strong><?=e($u['name'])?></strong></td><td><?=e($u['email'])?></td><td><span class="pill technical">Student</span></td><td><?=date('d M Y',strtotime($u['created_at']))?></td><td><a class="text-button" href="<?=url('admin/account-edit.php?role=student&id='.$u['id'])?>">Edit account</a> · <span class="admin-state <?=$u['is_active']?'published':'draft'?>"><?=$u['is_active']?'Active':'Inactive'?></span> <form class="inline-form" method="post" onsubmit="return confirm('<?=$u['is_active']?'Deactivate':'Activate'?> this student account?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="set_student_status"><input type="hidden" name="student_id" value="<?=$u['id']?>"><input type="hidden" name="is_active" value="<?=$u['is_active']?0:1?>"><button class="text-button" type="submit"><?=$u['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No student accounts are registered yet.</div><?php endif;?></section><?php else:?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('people')?></span><div><h2>Create committee account</h2><p>Committee members can access only the events assigned below and their applications.</p></div></div><?php if(!$events):?><div class="empty">Create at least one event before assigning committee access.</div><?php else:?><form method="post" class="form-card admin-event-form" autocomplete="off"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_committee"><div class="admin-form-grid"><label>Full name<input name="name" maxlength="120" required></label><label>University email<input type="email" name="email" pattern=".+@marwadiuniversity\.ac\.in" required placeholder="name@marwadiuniversity.ac.in"></label><label>Temporary password<input type="password" name="password" minlength="8" required></label></div><fieldset class="committee-event-picker"><legend>Assign events</legend><div class="committee-event-options"><?php foreach($events as $event):?><label><input type="checkbox" name="event_ids[]" value="<?=$event['id']?>"><span><?=e($event['title'])?><small><?=date('d M Y',strtotime($event['event_date']))?> · <?=e($event['venue'])?></small></span></label><?php endforeach;?></div></fieldset><div class="admin-form-actions"><span class="profile-role">Committee role is separate. Existing Admin and Student roles stay unchanged.</span><button class="btn primary" type="submit">Create Committee Account</button></div></form><?php endif;?></section><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('people')?></span><div><h2>Committee directory <span class="admin-count"><?=count($rows)?></span></h2><p>Manage each committee member’s assigned event access and account status.</p></div></div><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Assigned events</th><th>Joined</th><th>Access & status</th></tr></thead><tbody><?php foreach($rows as $u):$assignedIds=array_filter(array_map('intval',explode(',',$u['assigned_event_ids']??'')));?><tr><td><strong><?=e($u['name'])?></strong></td><td><?=e($u['email'])?></td><td><?=e(str_replace('||',', ',$u['assigned_events']??''))?:'No events assigned'?></td><td><?=date('d M Y',strtotime($u['created_at']))?></td><td><?php if($events):?><details class="committee-assignment-edit"><summary>Edit assignments</summary><form method="post" class="committee-assignment-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="assign_events"><input type="hidden" name="committee_id" value="<?=$u['id']?>"><?php foreach($events as $event):?><label><input type="checkbox" name="event_ids[]" value="<?=$event['id']?>" <?=in_array((int)$event['id'],$assignedIds,true)?'checked':''?>><?=e($event['title'])?></label><?php endforeach;?><button class="btn primary" type="submit">Save assignments</button></form></details><?php endif;?><a class="text-button" href="<?=url('admin/account-edit.php?role=committee&id='.$u['id'])?>">Edit account</a> <form method="post" class="committee-account-state" onsubmit="return confirm('<?=$u['is_active']?'Deactivate':'Activate'?> this committee account?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="set_committee_status"><input type="hidden" name="committee_id" value="<?=$u['id']?>"><input type="hidden" name="is_active" value="<?=$u['is_active']?0:1?>"><button class="text-button" type="submit"><?=$u['is_active']?'Deactivate':'Activate'?></button><span class="admin-state <?=$u['is_active']?'published':'draft'?>"><?=$u['is_active']?'Active':'Inactive'?></span></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No committee accounts yet. Create one above and assign events.</div><?php endif;?></section><?php endif;?><?php require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
